/// <summary>
/// The <c>AVAPriceIncreaseCreateMissingPositions</c> class is the controller class for <c>AVAPriceIncrease</c>
/// </summary>
internal final class AVAPriceIncreaseCreateMissingPositions
extends RunBaseBatch implements BatchRetryable
{
    AVAPriceIncreaseSet         clsAVAPriceIncreaseSet;
    AVAPriceIncreasePercentage  clsAVAPriceIncreasePercentage;
    QueryRun                    clsQueryRun;
    Query                       clsQuery;

    //DialogField                 fieldContinue;
    KCS_GoodsGroup              clsKCS_GoodsGroup;
    AVAPriceIncreaseLine        clsAVAPriceIncreaseLine;
    //DialogRunbase               dialog;

    #define.CurrentVersion(1)
    #LOCALMACRO.ParmList
        clsAVAPriceIncreaseSet
    #ENDMACRO

}

