/// <summary>
///     AVA <c>buildQuery</c> method.
/// </summary>
private void buildQuery()
{
    QueryBuildDataSource    locQBDS;
    QueryBuildRange         locQueryRange;

    clsQuery = new Query();

    clsQuery.addDataSource(tableNum(KCS_GoodsGroup));
    locQBDS         = clsQuery.dataSourceTable(tableNum(KCS_GoodsGroup));
    locQueryRange   = locQBDS.addRange(fieldNum(KCS_GoodsGroup, KCS_GoodsId));
    locQueryRange.value(queryValue(SysQuery::valueUnlimited()));
    //locQueryRange.status(RangeStatus::Locked);

    locQBDS.addRange(fieldNum(KCS_GoodsGroup, KCS_GoodsDescription));

    clsQueryRun = new QueryRun(clsQuery);
}

/// <summary>
/// Determines whether the class is shown in the list of <c>Journal</c> types.
/// </summary>
/// <returns>
/// true if the class is shown in the list of <c>Journal</c> types; otherwise, false.
/// </returns>
/// <remarks>
/// A class that can be used in a batch journal is a class where the same parameters can be used
/// repeatedly. The dialog can be shown and the parameters can be changed but parameters of some
/// classes might build on data that is only valid for a short time. Running a class two times with the
/// same parameters is not always possible. If the <c>RunBaseBatch.canGoBatch</c> method returns false,
/// this method will not have any effect.
/// </remarks>
public boolean canGoBatchJournal()
{
    return true;
}

/// <summary>
/// Returns a class that contains the methods that are described by the <c>RunBaseDialogable</c>
/// interface.
/// </summary>
/// <returns>
/// A class that contains the methods that are described by the <c>RunBaseDialogable</c> interface.
/// </returns>
/// <remarks>
/// A dialog can be either built by using the <c>Dialog</c> class or by using a class that is created
/// in the Application Object Tree (AOT).
/// </remarks>
public Object dialog()
{
    FormRun formRun = classfactory.createQueryForm(this);

    formRun.init();
    return formRun;
}

/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();
    this.getLast();
    this.buildQuery();
}

/// <summary>
///     AVA <c>pack</c> method.
/// </summary>
/// <returns>
///     <c>container</c> as return value
/// </returns>
public container pack()
{
    return [#CurrentVersion, #ParmList, clsQueryRun.pack()];
}

