/// </returns>
public AVAPriceIncreaseSet parmAVAPriceIncreaseSet(AVAPriceIncreaseSet _avaPriceIncreaseSet = clsAVAPriceIncreaseSet)
{
    clsAVAPriceIncreaseSet = _avaPriceIncreaseSet;

    return clsAVAPriceIncreaseSet;
