/// <summary>
/// Retrieves the instance of the <c>QueryRun</c> class, which is used by the <c>queryPrompt</c> method.
/// </summary>
/// <returns>
/// The instance of the <c>QueryRun</c> class, which is used by the <c>queryPrompt</c> method.
/// </returns>
/// <remarks>
/// This method is used if a query prompt is the dialog, and if a Select menu item is added to a
/// dialog. Do not create the instance of the <c>QueryRun</c> class when this method is called. Do it
/// in the <c>unpack</c> method and the <c>initParmDefault</c> method, or in the <c>init</c> method.
/// </remarks>
public QueryRun queryRun()
{
    return clsQueryRun;
}

/// <summary>
/// Contains the code that does the actual job of the class.
/// </summary>
public void  run()
{
    #OCCRetryCount

    clsQueryRun.query().dataSourceTable(tableNum(KCS_GoodsGroup)).update(true);
    clsQueryRun.query().dataSourceTable(tableNum(KCS_GoodsGroup)).concurrencyModel(ConcurrencyModel::Optimistic);

    while (clsQueryRun.next())
    {
        clsKCS_GoodsGroup = clsQueryRun.get(tableNum(KCS_GoodsGroup));

        setPrefix(#PreFixField(clsKCS_GoodsGroup, KCS_GoodsId));

        try
        {
            ttsbegin;
            /*
            clsAVAPriceIncreaseLine.clear();
            clsAVAPriceIncreaseLine.initValue();
            clsAVAPriceIncreaseLine.PriceIncreaseSet        = clsAVAPriceIncreaseSet;
            clsAVAPriceIncreaseLine.KCS_GoodsId             = clsKCS_GoodsGroup.KCS_GoodsId;
            clsAVAPriceIncreaseLine.PriceIncreasePercentage = clsAVAPriceIncreasePercentage;
            if (clsAVAPriceIncreaseLine.validateWrite())
            {
                clsAVAPriceIncreaseLine.write();
            }
            */
            if (!AVAPriceIncreaseLine::findOrCreate(clsAVAPriceIncreaseSet, 
                                                    clsKCS_GoodsGroup.KCS_GoodsId, 
                                                    clsAVAPriceIncreasePercentage   ).RecId )
            {
                throw Exception::Error;
            }
            /*
            clsAVAPriceIncreaseLine.write();
            */                    
            ttscommit;
        }

        catch (Exception::Deadlock)
        {
            clsAVAPriceIncreaseLine = AVAPriceIncreaseLine::find(   clsAVAPriceIncreaseLine.PriceIncreaseSet, 
                                                                    clsAVAPriceIncreaseLine.KCS_GoodsId,
                                                                    true                                        );
            retry;
        }

        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    clsAVAPriceIncreaseLine = AVAPriceIncreaseLine::find(   clsAVAPriceIncreaseLine.PriceIncreaseSet, 
                                                                            clsAVAPriceIncreaseLine.KCS_GoodsId,
                                                                            true                                        );
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }

        catch (Exception::Error)
        {
            checkFailed("@SYS25904");
        }
    }
}

