/// <summary>
///     AVA <c>unpack</c> method.
/// </summary>
/// <param name="_packedClass">
///     <c>container</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean unpack(container _packedClass)
{
    Integer         version = conPeek(_packedClass,1);
    container       packedQuery;

    switch (version)
    {
        case #CurrentVersion:
            [version, #ParmList, packedQuery] = _packedClass;
            if (packedQuery)
            {
                clsQueryRun = new QueryRun(packedQuery);
            }
            break;

        default:
            return false;
    }

    return true;
}

