///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
static void  main(Args _args)
{
    if (!_args)
    {
        throw error("@SYS25407");
    }

    AVAPriceIncreaseCreateMissingPositions locClassInstance = AVAPriceIncreaseCreateMissingPositions::newAVAPriceIncreaseSet(_args.parm());

    if (locClassInstance.prompt())
    {
        locClassInstance.runOperation();
    }
}

